Section NtbF.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.
Variables (segs : list Segment) (A : pm_addrs) (L : heap_layout) (HI : heap_iface) (P : NESK.sink_policy).
Definition ntbf_spec (W pc : Z) : Prop :=
  NESK.sp_mode P ->
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (cr : credit) (sp r q osk : Z) (k : NESK.sink),
    hi_heap HI (NESK.sink_own k ++ LBX) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> PMSP.entry A L R M sp r 2 ->
    getr R 10%bv = Z_to_bv 64 q -> L5.u64_at segs M q osk -> sp <= q -> q + 8 <= hl_sptop L -> q mod 8 = 0 -> (q + 8 <= osk \/ osk + 24 <= q) ->
    sp <= osk -> osk + 24 <= hl_sptop L -> osk mod 8 = 0 -> NESK.sink_at segs L PMSP.T3 PMSP.T4 P M osk k ->
    NESK.sk_z k + W <= NESK.SMZ ->
    PMSP.credit_le (NESK.sink_pot P (NESK.sk_c k)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (k' : NESK.sink) (cr' : credit),
        regs_preserved R R' ->
        NESK.sink_at segs L PMSP.T3 PMSP.T4 P M' osk k' -> NESK.sk_z k' = NESK.sk_z k + W ->
        L5C.hpres L LBX sp (PMSP.pm_scr 2) [(osk, 24)] M M' ->
        PMSP.credit_keep cr cr' (NESK.sink_pot P (NESK.sk_c k)) (NESK.sink_pot P (NESK.sk_c k')) ->
        model_but_vm model model' -> hi_heap HI (NESK.sink_own k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes segs SCFG (PMSP.cfg segs R' r M' model') K) ->
    srealizes segs SCFG (PMSP.cfg segs R pc M model) K.
End NtbF.

Section Kit.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
