(* [comment removed for export] *)
Definition kctx : Prop :=
  PMS.layout L /\ heap_iface_ok L SCFG HI /\ NESK.sink_policy_ok P /\ NESK.sp_hb P NESK.SMZ
  /\ PMSP.pm_scr h = SCR
  /\ hi_heap HI (NECS.eown en k ++ LBX) cr M (m_vmmaps model) /\ PMSP.model_ok model /\ K []
  /\ PMSP.entry CAD L R M sp r h
  /\ sp <= ov /\ ov + 56 <= hl_sptop L /\ ov mod 8 = 0 /\ sp <= osk /\ osk + 24 <= hl_sptop L /\ osk mod 8 = 0
  /\ ov + 56 <= osk
  /\ enc_at M ov osk en /\ sink_atP M osk k
  /\ PMSP.credit_le (NESK.sink_pot P (NESK.sk_c k)) cr      (* [comment removed for export] *)
  /\ FR mod 16 = 0 /\ 16 <= FR /\ FR + 16384 <= SCR.      (* [comment removed for export] *)
