  pose proof CX as (LY & HIok & PO & HBS & HSCR & HH & MOK & K0 & ENT & Hov1 & Hov2 & Hov3 & Hosk1 & Hosk2 & Hosk3 & SEP2
                    & EA & SKA & CRED & FR16 & FRlo & FRhi);
  pose proof (PMKS.klayout_S L LY) as KL; pose proof (PMKS.sfoot_S L LY) as SF.

Let LB : list (Z * Z) := NECS.eown en k ++ LBX.
Let LBY : list (Z * Z) := enc_own en ++ LBX.
Let Ws : list L5.range := [(osk, 24)].

