Definition facts : Prop :=
  L5.ra_ok r /\ getr R (PMK.reg 1) = Z_to_bv 64 r /\ getr R (PMK.reg 2) = Z_to_bv 64 sp
  /\ sp mod 16 = 0 /\ hl_sptop L - 2 ^ 23 + SCR <= sp /\ sp <= hl_sptop L /\ (0x7fff80000000 <= hl_sptop L <= 2 ^ 47)
  /\ getr R (PMK.reg 3) = Z_to_bv 64 (pa_gp CAD) /\ getr R (PMK.reg 4) = Z_to_bv 64 (pa_tp CAD)
  /\ L5C.stk (hl_sptop L) M sp SCR /\ hl_img_lo L = 0x10000 /\ hl_img_hi L = 0xfa000.
