(* [comment removed for export] *)
Definition cinv (cells : list (Z * Z)) (Mi : word -> option byte) (mdi : Model) (cri : credit) (ki : NESK.sink) (lo hi : Z) : Prop :=
  Forall (fun c => L5.u64_at RSEGS Mi (fst c) (snd c)) cells
  /\ L5C.stk (hl_sptop L) Mi sp SCR /\ model_but_vm model mdi /\ PMSP.model_ok mdi
  /\ hi_heap HI (NECS.eown en ki ++ LBX) cri Mi (m_vmmaps mdi)
  /\ enc_at Mi ov osk en /\ sink_atP Mi osk ki
  /\ NESK.sk_z k + lo <= NESK.sk_z ki <= NESK.sk_z k + hi
  /\ PMK.ek L LBX sp SCR Ws M Mi /\ PMK.dk L LBX sp SCR M Mi
  /\ PMSP.credit_keep cr cri (NESK.sink_pot P (NESK.sk_c k)) (NESK.sink_pot P (NESK.sk_c ki)).
(* [comment removed for export] *)
Definition cells_ok (cells : list (Z * Z)) : Prop := Forall (fun c => sp - FR <= fst c /\ fst c + 8 <= sp) cells.

