(* [comment removed for export] *)
Lemma cinv_frame cells Mi Mj mdi cri ki lo hi wlo whi : cinv cells Mi mdi cri ki lo hi ->
  mem_grows Mi Mj -> (forall i, 0 <= i < 2 ^ 64 -> ~ (wlo <= i < whi) -> Mj (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
  sp - SCR <= wlo -> whi <= sp -> Forall (fun c => whi <= fst c \/ fst c + 8 <= wlo) cells -> cells_ok cells ->
  hi_heap HI (NECS.eown en ki ++ LBX) cri Mj (m_vmmaps mdi) ->
