(* [comment removed for export] *)
Section Calls.
Variable cells : list (Z * Z).
Hypothesis COK : cells_ok cells.

(* [comment removed for export] *)
Hypothesis PB : NESK.push_back_spec RSEGS CAD EE L HI PMSP.T3 PMSP.T4 P.
Lemma call_pb (lo hi ra pv : Z) (fxq : FPState) Rq Mq mdq crq kq :
  NESK.sp_mode P ->
  cinv cells Mq mdq crq kq lo hi -> 0 <= lo -> NESK.sk_z k + hi + 1 <= NESK.SMZ -> L5.ra_ok ra -> sp - FR <= pv -> pv + 1 <= sp ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 ra -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - FR) ->
  getr Rq (PMK.reg 3) = getr R (PMK.reg 3) -> getr Rq (PMK.reg 4) = getr R (PMK.reg 4) ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 osk -> getr Rq (PMK.reg 11) = Z_to_bv 64 pv ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, cinv cells M2 md2 cr2 k2 (lo + 1) (hi + 1) -> regs_preserved Rq R2 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 md2) K) ->
