Lemma call_ntbf (W pc : Z) (NTB : ntbf_spec RSEGS CAD L HI P W pc) (lo hi ra : Z) (fxq : FPState) Rq Mq mdq crq kq :
  NESK.sp_mode P ->
  cinv cells Mq mdq crq kq lo hi -> 0 <= lo -> 0 <= W -> NESK.sk_z k + hi + W <= NESK.SMZ -> L5.ra_ok ra ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 ra -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - FR) ->
  getr Rq (PMK.reg 3) = getr R (PMK.reg 3) -> getr Rq (PMK.reg 4) = getr R (PMK.reg 4) ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 (ov + 8) ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, cinv cells M2 md2 cr2 k2 (lo + W) (hi + W) -> regs_preserved Rq R2 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 md2) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Rq pc Mq mdq) K.
Proof.
