Theorem v_flush_ok : NECS.v_flush_spec RSEGS CAD AQ EE L HI P.
Proof.
  unfold NECS.v_flush_spec, NECS.eslot_spec.
  intros SPM a fx R M model K LBX cr sp r ov osk oec cat en k b e HH MOK K0 ENT A10 ARGS
         Hov1 Hov2 Hov3 Hosk1 Hosk2 Hosk3 Hoec1 Hoec2 Hoec3 SEP1 SEP2 EA SKA ECS BASE ERR PRE CRED KONT.
  destruct ENT as (Rra & RAok & Rsp & Rgp & Rtp & STK). pose proof RAok as (Hr1 & Hr2). pose proof MOK as (Mh & Ml & Mm). pose proof STK as (A16 & SLO & SHI & STOP & SDEF).
  rewrite L5K.rl1 in Rra.
  unfold PMSP.cfg. cbn [ne_flush EE NemLayoutS.NEADDR_S].
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| |].
  { apply (PMK.ret_to RSEGS fx R M 0x404e4 W_4049c r F_4049c eq_refl D_4049c); [exact Rra| lia| exact Hr2]. }
  apply (KONT fx R M model en k b e cr).
  - intros x Hx. reflexivity.
  - exact EA.
  - exact SKA.
  - exact ECS.
  - exact BASE.
  - exact ERR.
  - intros E0; exact E0.
  - intros E0; exact E0.
  - unfold NECS.step_none. split; [reflexivity|]. split; reflexivity.
  - apply (PMK.hpres_of L LBX sp (PMSP.pm_scr 0) _ M M).
    + intros i _. reflexivity.
    + change (PMSP.pm_scr 0) with 12288. exact SDEF.
    + intros i _ _ _ D. exact D.
  - unfold PMSP.credit_keep. split; lia.
  - apply L5C.model_but_vm_refl.
  - exact HH.
Qed.
