Import ListNotations. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module NECKS.
Import PMS.
Import NEM. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Abbreviation CAD := PMS.AD.
Abbreviation EE := NemLayoutS.NEADDR_S.
Local Ltac insub := intros ? Hx; rewrite ?in_app_iff in Hx; rewrite ?in_app_iff; tauto.

Lemma hdr_str_bounds n : 1 <= hdr_str n <= 5.
Proof. unfold hdr_str. destruct (n <=? 31); [lia|]. destruct (n <=? 255); [lia|]. destruct (n <=? 65535); lia. Qed.

(* [comment removed for export] *)
Lemma view_ok_mono (M : word -> option byte) sp sp' ov LBX p d n : sp' <= sp -> NECS.view_ok RSEGS M sp ov LBX p d n -> NECS.view_ok RSEGS M sp' ov LBX p d n.
Proof.
  intros H (V0 & V8 & NR & D & LOC & D0 & D47). unfold NECS.view_ok. repeat (split; [assumption|]).
  split; [| split; assumption]. destruct LOC as [X|[X|(X1 & X2 & X3)]]; [left; exact X| right; left; exact X| right; right]. split; [lia|]. split; assumption.
Qed.

Section Kit.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : NESK.sink_policy.
Variables (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet) (LBX : list (Z * Z)) (cr : credit).
Variables (sp r ov osk : Z) (en : enc) (k : NESK.sink) (h SCR FR : Z).
Hypothesis CX : NECK.kctx L HI P R M model K LBX cr sp r ov osk en k h SCR FR.
Variable cells : list (Z * Z).
Hypothesis COK : NECK.cells_ok sp FR cells.

Abbreviation cinv := (NECK.cinv L HI P M model LBX cr sp ov osk en k SCR cells).
Let Ws : list L5.range := [(osk, 24)].

(* [comment removed for export] *)
Lemma call_wsv (WSV : NECS.wsv_spec RSEGS CAD EE L HI P) (lo hi ra p d n : Z) (bs : list Z) (fxq : FPState) Rq Mq mdq crq kq :
  NESK.sp_mode P -> FR + 18432 <= SCR ->
  cinv Mq mdq crq kq lo hi -> 0 <= lo -> NESK.sk_z k + hi + hdr_str n + n <= NESK.SMZ -> L5.ra_ok ra ->   (* [comment removed for export] *)
  getr Rq (PMK.reg 1) = Z_to_bv 64 ra -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - FR) ->
  getr Rq (PMK.reg 3) = getr R (PMK.reg 3) -> getr Rq (PMK.reg 4) = getr R (PMK.reg 4) ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 ov -> getr Rq (PMK.reg 11) = Z_to_bv 64 p -> sp - FR <= p -> p + 16 <= ov ->
  NECS.view_ok RSEGS Mq (sp - FR) ov LBX p d n -> L5.bytes_at RSEGS Mq d bs -> Z.of_nat (length bs) = n -> utf8_valid bs = true -> bytes_ok bs ->
  PMST.base_ok RSEGS CAD Mq ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, cinv M2 md2 cr2 k2 (lo + hdr_str n + n) (hi + hdr_str n + n) -> regs_preserved Rq R2 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 md2) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Rq (ne_write_string_value EE) Mq mdq) K.
Proof.
  pose proof CX as (LY & HIok & PO & HBS & HSCR & HH & MOK & K0 & ENT & Hov1 & Hov2 & Hov3 & Hosk1 & Hosk2 & Hosk3 & SEP2 & EA & SKA & CRED & FR16 & FRlo & FRhi).
  pose proof (PMKS.klayout_S L LY) as KL.
  intros SPM FRhi3 INV LO0 Hhi RAq Q1 Q2 Q3 Q4 Q10 Q11 Hp1 Hp2 VOK BS BSL UTF BOK BASEq KX.
  destruct (NECK.facts_ok L HI P R M model K LBX cr sp r ov osk en k h SCR FR CX) as (RAok & Rra & Rsp & A16 & SLO & SHI & STOP & Rgp & Rtp & STK & IMLO & IMHI).
  pose proof INV as (C & STKq & MBq & MOKq & HHq & EAq & SKAq & Zq & EKq & DKq & CKq).
  pose proof MOKq as (Mhq & Mlq & Mmq).
  assert (SC0 : 0 <= SCR) by (clear - FRhi FRlo; lia).
  assert (STKcq : L5C.stk (hl_sptop L) Mq (sp - FR) 18432).
  { apply (PMK.stk_call L Mq sp SCR (sp - FR) 18432 STKq); [clear - FRlo; lia| clear - FRhi3; lia| clear - FRhi3 FRlo; lia|].
    assert (E16 : FR = FR / 16 * 16) by (clear - FR16; pose proof (Z.div_mod FR 16 ltac:(lia)); lia).
    replace (sp - FR) with (sp + (- (FR / 16)) * 16) by (clear - E16; lia). rewrite Z.mod_add by (clear; lia). exact A16. }
  pose proof (hdr_str_bounds n) as HSB.
  pose proof WSV as WTX. unfold NECS.wsv_spec in WTX.
  apply (WTX SPM fxq Rq Mq mdq K LBX crq (sp - FR) ra ov osk p d n bs en kq); clear WTX.
  { exact HHq. }
  { exact MOKq. }
  { exact K0. }
  { unfold PMSP.entry. rewrite L5K.rl1, L5K.rl2, L5K.rl3, L5K.rl4. split; [exact Q1|]. split; [exact RAq|]. split; [exact Q2|].
    split; [rewrite Q3; exact Rgp|]. split; [rewrite Q4; exact Rtp|]. exact STKcq. }
  { rewrite L5K.rl10. exact Q10. } { rewrite L5K.rl11. exact Q11. } { exact Hp1. } { exact Hp2. } { exact VOK. } { exact BS. } { exact BSL. } { exact UTF. } { exact BOK. }
  { clear - Hov1 FRlo; lia. } { exact Hov2. } { exact Hov3. } { clear - Hosk1 FRlo; lia. } { exact Hosk2. } { exact Hosk3. } { exact SEP2. }
  { exact EAq. } { exact SKAq. } { exact BASEq. }
  { clear - Zq Hhi LO0; lia. }
  { unfold PMSP.credit_le, PMSP.credit_keep in CRED, CKq |- *. clear - CRED CKq. lia. }
  intros fx2 R2 M2 md2 k2 cr2 RP2 EA2 SKA2 Z2 HP2 CK2 MB2 HH2.
  change (PMSP.pm_scr 3) with 18432 in HP2.
  pose proof (PMFR.model_ok_but_vm mdq md2 MOKq MB2) as MOK2.
  assert (STK2 : L5C.stk (hl_sptop L) M2 sp SCR) by (apply (PMK.stk_after RSEGS L KL LBX Mq M2 sp SCR (sp - FR) 18432 _ STKq HP2); clear - FRlo FRhi3; lia).
  pose proof (PMK.ek_of_hpres L LBX (sp - FR) 18432 [(osk, 24)] Mq M2 HP2) as EK2.
  assert (SC2 : 0 <= 18432) by (clear; lia).
  apply (KX fx2 R2 M2 md2 cr2 k2); [| exact RP2].
  unfold NECK.cinv. split.
  { pose proof COK as COK'. unfold NECK.cells_ok in COK'. rewrite Forall_forall in C, COK' |- *. intros c Hc. pose proof (C c Hc) as U. pose proof (COK' c Hc) as Oc.
    apply (PMFR.u64_keep RSEGS L KL LBX (sp - FR) 18432 _ Mq M2 EK2 STKcq SC2); [clear - Oc; lia| clear - Oc SHI STOP; lia| intros i Hi I; apply PMFR.inW_inv1 in I; clear - I Hi Oc Hosk1; lia| exact U]. }
  split; [exact STK2|]. split; [exact (L5C.model_but_vm_trans _ _ _ MBq MB2)|]. split; [exact MOK2|].
  split; [exact HH2|]. split; [exact EA2|]. split; [exact SKA2|].
  split; [clear - Zq Z2; lia|].
  split.
  { apply (PMK.ek_trans L LBX sp SCR Ws M Mq M2 EKq).
    apply (PMK.ek_callee_in' RSEGS L KL LBX LBX sp SCR (sp - FR) 18432 Ws [(osk, 24)] Mq M2 HP2 ltac:(apply incl_refl)); [clear - FRhi3; lia| clear - FRlo; lia| unfold hl_ceil; clear - SLO; lia| clear - STOP; lia| exact (PMFR.brange_hi L LBX (NECK.BRX L HI P R M model K LBX cr sp r ov osk en k h SCR FR CX))|].
    intros a0 I. apply PMFR.inW_inv1 in I. right. apply PMK.inW_here. exact I. }
  split; [apply (PMK.dk_trans L LBX sp SCR M Mq M2 DKq); apply (PMK.dk_callee L LBX LBX sp SCR (sp - FR) 18432 _ Mq M2 HP2 ltac:(apply incl_refl)); clear - FRlo FRhi3; lia|].
  unfold PMSP.credit_keep in CKq, CK2 |- *. clear - CKq CK2. lia.
Qed.
End Kit.
